// MB-Studio kernel - plugin interface.
//
// Everything above the kernel is a plugin: the MB-System adapter that turns
// the mbio library and the command line programs into services, and the
// graphical user interface itself. A plugin is a shared library named
// "mbstudio-plugin-<name>" that exports three C functions (generated by
// MBSTUDIO_DECLARE_PLUGIN):
//
//   int                 mbstudio_plugin_abi_version();
//   mbstudio::IPlugin  *mbstudio_create_plugin();
//   void                mbstudio_destroy_plugin(mbstudio::IPlugin *);
#pragma once

#include <string>
#include <vector>

#include "mbstudio/kernel/Export.h"

namespace mbstudio {

// Incremented whenever the kernel interfaces change incompatibly.
constexpr int kPluginAbiVersion = 2;  // 2: contribution registry, command categories

class Kernel;

struct PluginInfo {
  std::string id;           // unique, e.g. "mbsystem"
  std::string name;         // human readable
  std::string version;
  std::string description;
  std::vector<std::string> dependencies;  // ids of plugins that must start first
};

class IPlugin {
 public:
  virtual ~IPlugin() = default;
  virtual PluginInfo info() const = 0;
  // Register services, commands and event handlers. Return false (and set
  // error) if the plugin cannot work in this environment.
  virtual bool initialize(Kernel &kernel, std::string &error) = 0;
  // Called in reverse start order. Services and commands registered under the
  // plugin id are removed by the kernel afterwards.
  virtual void shutdown(Kernel &kernel) { (void)kernel; }
};

}  // namespace mbstudio

#define MBSTUDIO_DECLARE_PLUGIN(PluginClass)                                                \
  extern "C" MBSTUDIO_PLUGIN_EXPORT int mbstudio_plugin_abi_version() {                     \
    return mbstudio::kPluginAbiVersion;                                                    \
  }                                                                                        \
  extern "C" MBSTUDIO_PLUGIN_EXPORT mbstudio::IPlugin *mbstudio_create_plugin() {           \
    return new PluginClass();                                                              \
  }                                                                                        \
  extern "C" MBSTUDIO_PLUGIN_EXPORT void mbstudio_destroy_plugin(mbstudio::IPlugin *plugin) { \
    delete plugin;                                                                         \
  }
